'use strict';
const $ = id => document.getElementById(id);
const esc = value => String(value ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const clone = value => JSON.parse(JSON.stringify(value));
const paths = {
 Document:'M6 3h8l4 4v14H6z M14 3v5h5 M9 12h6 M9 16h6',
 Setting:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M12 3v2 M12 19v2 M3 12h2 M19 12h2 M5.5 5.5l1.5 1.5 M17 17l1.5 1.5 M5.5 18.5L7 17 M17 7l1.5-1.5',
 Connection:'M4 4h6v6H4z M14 14h6v6h-6z M14 4h6v6h-6z M7 10v7h7 M10 7h4',
 User:'M12 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M4 21v-3a6 6 0 0 1 6-5h4a6 6 0 0 1 6 5v3',
 DataAnalysis:'M4 3v17h17 M8 15v-5 M13 15V6 M18 15v-8',
 Box:'m3 7 9-4 9 4-9 4z M3 7v10l9 4 9-4V7 M12 11v10 M7.5 5l9 4',
 Picture:'M3 4h18v16H3z M3 16l6-6 4 4 3-3 5 6 M15 8h.01',
 OfficeBuilding:'M5 21V3h14v18 M9 7h1 M14 7h1 M9 11h1 M14 11h1 M10 21v-6h4v6 M3 21h18',
 Reading:'M12 5v16 M12 5C8 2 5 3 2 4v15c4-1 7-1 10 2 3-3 6-3 10-2V4c-3-1-6-2-10 1',
 Brush:'m14 4 5-1-1 5-9 9-4-4z M5 13c-5 1 0 6-3 8 6 0 7-1 7-4',
 Search:'M10 3a7 7 0 1 0 0 14 7 7 0 0 0 0-14 M15 15l6 6',
 Lock:'M5 10h14v11H5z M8 10V7a4 4 0 0 1 8 0v3',
 Clock:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 6v6l4 3',
 Info:'M12 2a10 10 0 1 0 0 20 10 10 0 0 0 0-20 M12 11v6 M12 7h.01',
 Fold:'M3 4h18v16H3z M8 4v16 M16 8l-4 4 4 4',
 Money:'M3 5h18v14H3z M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M6 12h.01 M18 12h.01',
 Van:'M2 6h12v12H2z M14 10h4l4 4v4h-8 M6 16a2 2 0 1 0 0 4 2 2 0 0 0 0-4 M18 16a2 2 0 1 0 0 4 2 2 0 0 0 0-4',
 Monitor:'M3 3h18v14H3z M12 17v4 M8 21h8',
 Aim:'M12 3a9 9 0 1 0 0 18 9 9 0 0 0 0-18 M12 7a5 5 0 1 0 0 10 5 5 0 0 0 0-10 M12 11v2',
 Lightning:'m13 2-9 12h7l-1 8 10-13h-7z',
 Shop:'M3 9h18l-2-6H5z M4 9v12h16V9 M9 21v-7h6v7',
 Calendar:'M3 5h18v16H3z M3 10h18 M7 2v6 M17 2v6',
 Key:'M7 3a4 4 0 1 0 0 8 4 4 0 0 0 0-8 M10 10l11 11 M17 17l3-3 M14 14l3-3',
 Folder:'M3 6h7l2 3h9v11H3z',
 Finished:'M4 12l5 5L20 6',
 List:'M8 5h13 M8 12h13 M8 19h13 M3 5h.01 M3 12h.01 M3 19h.01'
};
const aliases={Notebook:'Reading',Collection:'Folder',CollectionTag:'Folder',Goods:'Box',Wallet:'Money',Tickets:'Document',Postcard:'Document',Stamp:'Finished',UserFilled:'User',DataLine:'DataAnalysis',DataBoard:'DataAnalysis',TrendCharts:'DataAnalysis',Camera:'Picture',MagicStick:'Brush',EditPen:'Brush',Printer:'Document',Upload:'Document',Refresh:'Clock',ChatDotRound:'Document'};
function icon(name){return `<svg aria-hidden="true" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.6" stroke-linecap="round" stroke-linejoin="round"><path d="${paths[name]||paths[aliases[name]]||paths.Document}"/></svg>`;}
document.querySelectorAll('[data-icon]').forEach(el=>{el.innerHTML=icon(el.dataset.icon);});
const STORAGE='ark-navigation-design-v1';
let published=clone(NAV_SNAPSHOT.nodes),draft=clone(published),version=1;
let history=[{version:1,time:'初始源码快照',summary:'默认导航结构',nodes:clone(published)}],saved=JSON.stringify(draft);
let storageError='';
try{const stored=JSON.parse(localStorage.getItem(STORAGE)||'null');if(stored&&stored.hash===NAV_SNAPSHOT.hash&&Array.isArray(stored.draft)){({published,draft,version,history}=stored);saved=JSON.stringify(draft);}}catch{storageError='本地存储不可用，演示改动只在当前页面保留';}
let selected='invoice',query='',filter='all',compact=false,expanded=new Set(['invoice','system','colorwork']);
let toastTimer,dragged='',modalSubmit=null,lastFocus=null;
const get = id => draft.find(n=>n.id===id);
const children = parent => draft.filter(n=>n.parent===parent).sort((a,b)=>a.order-b.order||a.id.localeCompare(b.id));
function depth(node){let level=0,p=get(node.parent);while(p&&level<5){level++;p=get(p.parent);}return level;}
function descendants(id){return children(id).flatMap(n=>[n,...descendants(n.id)]);}
function rootOf(node){let p=node;while(get(p.parent))p=get(p.parent);return p;}
function effectiveVisible(n){return n.visible&&(!get(n.parent)||effectiveVisible(get(n.parent)));}
function isVisible(n){return effectiveVisible(n)&&(n.kind==='page'||descendants(n.id).some(c=>c.kind==='page'&&effectiveVisible(c)));}
function changes(){const before=new Map(published.map(n=>[n.id,n]));const keys=['label','icon','parent','order','visible','badge','badgePlace','badgeTone','titleSync'];return draft.filter(n=>!before.has(n.id)||keys.some(k=>n[k]!==before.get(n.id)[k])).map(n=>({node:n,before:before.get(n.id)})).concat(published.filter(n=>!get(n.id)).map(n=>({node:null,before:n})));}
function validate(){for(const n of draft){if(!n.label.trim()||[...n.label.trim()].length>24)return {id:n.id,message:'名称须为 1–24 个字符'};if([...(n.badge||'')].length>8)return {id:n.id,message:'文字角标最多 8 个字符'};if(draft.some(c=>c.id!==n.id&&c.parent===n.parent&&c.label.trim().toLocaleLowerCase()===n.label.trim().toLocaleLowerCase()))return {id:n.id,message:'同一分类下的名称不能重复'};if(n.parent&&!get(n.parent))return {id:n.id,message:'所属分类不存在'};}return null;}
function toast(message){$('toast').textContent=message;$('toast').classList.add('toast-visible');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('toast').classList.remove('toast-visible'),3600);}
function status(){const dirty=JSON.stringify(draft)!==saved,count=changes().length,error=validate();$('version-label').textContent=`演示版本 V${version}`;$('draft-label').textContent=dirty?`${count} 项变更 · 未保存`:count?`${count} 项变更 · 草稿已保存`:'与当前版本一致';$('save-btn').disabled=!dirty||!!error;$('publish-btn').disabled=!count||!!error;$('tree-count').textContent=`${draft.filter(n=>n.kind==='group'&&!n.parent).length} 个分类`;$('hidden-count').textContent=draft.filter(n=>!n.visible).length;const err=$('field-error');if(err)err.textContent=error?.id===selected?error.message:'';}
function badge(n){return n.badge?`<span class="badge-demo ${esc(n.badgeTone||'gold')}">${esc(n.badge)}</span>`:'';}
function matches(n){return (!query||`${n.label} ${n.original} ${n.path||''}`.toLowerCase().includes(query.toLowerCase()))&&(filter!=='hidden'||!effectiveVisible(n));}
function renderTree(){const position=$('tree').scrollTop;const filtered=!!query||filter==='hidden';function rows(parent){return children(parent).map(n=>{const subs=descendants(n.id),match=matches(n),subMatch=subs.some(matches);if(!match&&!subMatch)return '';const open=filtered||expanded.has(n.id);return `<div class="tree-row ${n.id===selected?'selected':''} ${!effectiveVisible(n)?'hidden-node':''}" data-node="${esc(n.id)}" style="padding-left:${depth(n)*15}px"><span class="grip" draggable="${!filtered}" data-drag="${esc(n.id)}" title="拖动调整同级顺序" aria-hidden="true">⠿</span>${n.kind==='group'?`<button class="toggle" data-expand="${esc(n.id)}" aria-label="${open?'收起':'展开'}${esc(n.label)}" aria-expanded="${open}">${open?'⌄':'›'}</button>`:'<span style="width:21px"></span>'}<button class="node-select" data-select="${esc(n.id)}" ${n.id===selected?'aria-current="true"':''} title="${esc(n.label)}">${icon(n.icon)}<span class="node-name">${esc(n.label)}</span></button>${!n.visible?'<span class="tiny">隐藏</span>':''}${n.protected?'<span class="tiny">保留</span>':''}${n.kind==='group'?`<span class="row-count">${subs.filter(s=>s.kind==='page').length}</span>`:''}</div>${n.kind==='group'&&open?rows(n.id):''}`;}).join('');} $('tree').innerHTML=rows('')||'<div class="empty">没有找到匹配的导航<br><button id="clear-filter">清空筛选</button></div>';$('tree').scrollTop=position;}
function parentOptions(n){let candidates=draft.filter(g=>g.kind==='group'&&g.id!==n.id&&!descendants(n.id).some(x=>x.id===g.id));if(n.kind==='group')candidates=candidates.filter(g=>!g.parent&&children(n.id).every(x=>x.kind!=='group'));return `${!n.path?.startsWith('https:')?`<option value="">${n.kind==='group'?'一级分类':'一级页面'}</option>`:''}`+candidates.map(g=>`<option value="${esc(g.id)}" ${n.parent===g.id?'selected':''}>${esc(g.parent?get(g.parent).label+' / ':'')}${esc(g.label)}</option>`).join('');}
function renderEditor(){const n=get(selected);if(!n)return;const group=n.kind==='group',siblings=children(n.parent),idx=siblings.findIndex(x=>x.id===n.id),filtered=query||filter!=='all';$('kind-label').textContent=group?(n.parent?'二级分类':'一级分类'):(n.path?.startsWith('https:')?'外部入口':'页面入口');$('editor').innerHTML=`<div class="editor-content"><div class="selection-head"><div class="selection-icon">${icon(n.icon)}</div><div><h3 id="selection-title">${esc(n.label)}</h3><p>${group?`${descendants(n.id).filter(c=>c.kind==='page').length} 个页面入口`:`${esc(n.path)}`}</p></div></div><div class="field"><div class="label-row"><label for="label-input">${group?'分类名称':'导航名称'}</label><span>最多 24 字</span></div><input id="label-input" value="${esc(n.label)}" autocomplete="off"><p class="hint">${group?'分类名称会同步用于导航搜索。':`原名称：${esc(n.original)}`}</p></div><div id="field-error" class="field-error" role="alert"></div><div class="two-col"><div class="field"><label for="icon-btn">导航图标</label><button id="icon-btn" class="icon-picker-trigger">${icon(n.icon)}<span>${esc(n.icon)}</span><span>⌄</span></button></div><div class="field"><label for="parent-input">${group?'分类层级 / 归属':'所属分类'}</label><select id="parent-input" ${n.protected||(group&&n.builtin)?'disabled':''}>${parentOptions(n)}</select></div></div>${!group?`<label class="switch-row"><input type="checkbox" id="title-sync" ${n.titleSync?'checked':''}>同时更新此页面的标题与页签</label>`:''}<div class="section-label">角标设置 <span>装饰标签与业务提醒分开维护</span></div><div class="field"><label for="badge-input">文字角标</label><input id="badge-input" placeholder="例如 NEW、试用、BY 加程" value="${esc(n.badge||'')}"><p class="hint">最多 8 字；留空则不显示。</p></div><div class="two-col"><div class="field"><label for="badge-place">显示位置</label><select id="badge-place"><option value="text" ${n.badgePlace!=='icon'?'selected':''}>名称右侧</option><option value="icon" ${n.badgePlace==='icon'?'selected':''}>图标右上角</option></select></div><div class="field"><label for="badge-tone">角标样式</label><select id="badge-tone">${[['gold','品牌金'],['blue','信息蓝'],['neutral','中性灰']].map(([v,t])=>`<option value="${v}" ${n.badgeTone===v?'selected':''}>${t}</option>`).join('')}</select></div></div>${n.business?`<div class="protected">${icon('Lock')}业务提醒 · ${n.business==='domesticReviews'?'待审核数量':'单据异常'}由系统生成，不允许手填覆盖。</div>`:''}<div class="section-label">显示设置</div><label class="switch-row"><input id="visible-input" type="checkbox" ${n.visible?'checked':''} ${n.protected?'disabled':''}>在导航中显示</label><p class="hint">${n.protected?'系统保留入口，始终可供有权限的用户访问。':'隐藏入口不会更改页面的访问权限。'}${!group&&n.phase?' 该入口还受交易阶段限制。':''}</p>${group?'':`<div class="read-only" style="margin-top:16px"><strong>访问规则 · 只读</strong>${esc(n.rule)}<div class="hint">移动分类后仍沿用原访问限制。</div></div>`}</div><div class="editor-actions"><div><button id="up-btn" ${idx<=0||n.protected||filtered?'disabled':''}>↑ 上移</button><button id="down-btn" ${idx===siblings.length-1||n.protected||filtered?'disabled':''}>↓ 下移</button></div>${group&&!n.parent?'<button id="subgroup-btn">＋ 二级分类</button>':group&&!n.builtin?'<button id="delete-btn" class="danger">删除分类</button>':'<button id="reset-btn" class="text-button">恢复默认展示</button>'}</div>${group&&!n.builtin&&!n.parent?'<div style="padding:0 18px 12px"><button id="delete-btn" class="text-button danger">删除空分类</button></div>':''}`;
 $('label-input').addEventListener('input',e=>{n.label=e.target.value;$('selection-title').textContent=n.label;refresh(false);});
 $('badge-input').addEventListener('input',e=>{n.badge=e.target.value;refresh(false);});
 $('badge-place').onchange=e=>{n.badgePlace=e.target.value;refresh(false);};$('badge-tone').onchange=e=>{n.badgeTone=e.target.value;refresh(false);};
 $('visible-input').onchange=e=>{n.visible=e.target.checked;refresh(false);if(!n.visible&&group)toast(`草稿中将隐藏 ${descendants(n.id).filter(x=>x.kind==='page').length} 个后代页面入口`);};
 $('parent-input').onchange=e=>{n.parent=e.target.value;n.order=Math.max(0,...children(n.parent).map(x=>x.order))+1;expanded.add(n.parent);refresh();toast('归属已调整，原访问限制保持不变');};
 if($('title-sync'))$('title-sync').onchange=e=>{n.titleSync=e.target.checked;status();};
 $('icon-btn').onclick=()=>openIcons(n);$('up-btn').onclick=()=>move(-1);$('down-btn').onclick=()=>move(1);
 if($('subgroup-btn'))$('subgroup-btn').onclick=()=>openNew(n.id);
 if($('delete-btn'))$('delete-btn').onclick=()=>removeGroup(n);
 if($('reset-btn'))$('reset-btn').onclick=()=>{const original=NAV_SNAPSHOT.nodes.find(x=>x.id===n.id);if(original){for(const key of ['label','icon','badge','badgePlace','badgeTone','titleSync'])n[key]=original[key];refresh();toast('默认展示已恢复到草稿');}};
}
function previewRow(n){const label=n.business?(n.business==='domesticReviews'?'<span class="badge-demo blue" title="演示数量，并非实时数据">3</span>':'<span class="badge-demo gold" title="演示异常提示">!</span>'):n.badgePlace!=='icon'?badge(n):'';return `<div class="preview-row ${n.kind==='group'?'group':''} ${n.id===selected?'selected':''}" title="${esc(n.label)}"><span class="preview-icon">${icon(n.icon)}${!n.business&&n.badgePlace==='icon'?badge(n):''}</span>${compact?'':`<span class="preview-name">${esc(n.label)}</span>${label}`}</div>`;}
function renderPreview(){const n=get(selected),root=rootOf(n);let content='';function branch(parent){return children(parent).filter(isVisible).map(c=>c.kind==='group'?`<div class="preview-subgroup">${esc(c.label)}</div>${branch(c.id)}`:previewRow(c)).join('');}if(isVisible(root)){content=previewRow(root)+(compact?'':branch(root.id));}else content=`<div class="preview-empty">${root.visible?'空分类暂不展示':'此分类已在草稿中隐藏'}</div>`;$('preview').innerHTML=`<div class="preview-shell ${compact?'compact':''}"><div class="preview-brand">${compact?'L':'LeShine'}</div>${compact?'':'<div class="preview-caption">NAVIGATION</div>'}${content}${!compact?'<p class="preview-note">数字与异常标记为演示样例</p>':''}</div>`;}
function refresh(editor=true){renderTree();if(editor)renderEditor();renderPreview();status();}
function move(direction){const n=get(selected),siblings=children(n.parent),idx=siblings.findIndex(x=>x.id===n.id),target=idx+direction;if(target<0||target>=siblings.length||n.protected)return;[siblings[idx],siblings[target]]=[siblings[target],siblings[idx]];siblings.forEach((x,i)=>x.order=i);refresh();toast('同级顺序已更新');}
function persist(){try{localStorage.setItem(STORAGE,JSON.stringify({hash:NAV_SNAPSHOT.hash,published,draft,version,history}));saved=JSON.stringify(draft);return true;}catch{toast('本地存储不可用，未保存；请保留此页面');return false;}}
function openModal(title,body,footer,submit){lastFocus=document.activeElement;$('modal-title').textContent=title;$('modal-body').innerHTML=body;$('modal-footer').innerHTML=footer;modalSubmit=submit;$('modal').showModal();$('modal').querySelector('[autofocus]')?.focus();}
function closeModal(){$('modal').close();lastFocus?.focus();}
$('modal-close').onclick=closeModal;$('modal').addEventListener('close',()=>lastFocus?.focus());$('modal-form').onsubmit=e=>{e.preventDefault();modalSubmit?.();};$('modal-footer').onclick=e=>{if(e.target.closest('[data-cancel]'))closeModal();};
const cancelButton='<button type="button" data-cancel>取消</button>';
const iconNames={DataAnalysis:'数据分析',User:'用户',Connection:'导航连接',OfficeBuilding:'企业',Document:'文档',Money:'金额',List:'列表',Van:'物流',Box:'库存',Setting:'设置',Aim:'目标',Reading:'知识',Brush:'画笔',Shop:'店铺',Monitor:'工作台',Lock:'锁定',Calendar:'日历',Picture:'图片',Folder:'文件夹',Lightning:'闪电',Key:'凭证',Finished:'完成'};
function openIcons(n){openModal('选择导航图标','<label for="icon-search">搜索图标</label><input id="icon-search" autofocus placeholder="输入中文名称或英文标识"><div id="icon-grid" class="icon-grid"></div>',cancelButton);const render=()=>{const q=$('icon-search').value.toLowerCase();$('icon-grid').innerHTML=[...new Set([...NAV_SNAPSHOT.icons,'Folder'])].filter(name=>`${name} ${iconNames[name]||''}`.toLowerCase().includes(q)).map(name=>`<button type="button" class="icon-option ${n.icon===name?'picked':''}" data-icon-name="${name}">${icon(name)}<span>${esc(iconNames[name]||name)}</span><span>${name}</span></button>`).join('')||'<p class="muted">没有匹配图标</p>';};$('icon-search').oninput=render;$('icon-grid').onclick=e=>{const b=e.target.closest('[data-icon-name]');if(!b)return;n.icon=b.dataset.iconName;closeModal();refresh();};render();}
function openNew(parent=''){openModal(parent?'新增二级分类':'新增一级分类',`<p>${parent?`添加到「${esc(get(parent).label)}」`:'为团队创建新的工作分类。创建后可将已有页面移入。'}</p><div class="field"><label for="new-name">分类名称</label><input id="new-name" autofocus placeholder="例如：财务协同" required maxlength="24"></div><div class="field"><label for="new-parent">所属位置</label><select id="new-parent"><option value="">主导航 · 一级分类</option>${draft.filter(n=>n.kind==='group'&&!n.parent).map(n=>`<option value="${esc(n.id)}" ${n.id===parent?'selected':''}>${esc(n.label)} · 二级分类</option>`).join('')}</select></div><p class="hint">空分类会保留在管理页，加入可访问页面后才出现在员工侧栏。</p><div id="new-error" class="field-error" role="alert"></div>`,cancelButton+'<button class="primary" type="submit">创建分类</button>',()=>{const label=$('new-name').value.trim(),p=$('new-parent').value;if(!label||[...label].length>24||children(p).some(n=>n.label.trim().toLocaleLowerCase()===label.toLocaleLowerCase())){$('new-error').textContent='请填写 1–24 字且同级不重复的名称';return;}const id='custom-'+crypto.randomUUID();draft.push({id,kind:'group',parent:p,label,original:label,icon:'Folder',order:Math.max(0,...children(p).map(n=>n.order))+1,visible:true,builtin:false,badge:'',badgePlace:'text',badgeTone:'gold'});selected=id;expanded.add(p);expanded.add(id);closeModal();refresh();toast('分类已创建，可通过页面的“所属分类”移入入口');});}
function removeGroup(n){if(children(n.id).length){toast('该分类仍有子项，请先将全部子项移走');return;}openModal('删除空分类',`<p>删除草稿中的「${esc(n.label)}」？不会删除任何业务页面或业务数据。</p>`,cancelButton+'<button class="danger" type="submit">删除分类</button>',()=>{draft=draft.filter(x=>x.id!==n.id);selected=n.parent||'invoice';closeModal();refresh();});}
const fieldNames={label:'名称',icon:'图标',parent:'归属',order:'顺序',visible:'显示',badge:'文字角标',badgePlace:'角标位置',badgeTone:'角标样式',titleSync:'同步页面标题'};
function displayValue(key,value,old=false){if(key==='parent')return (old?published.find(n=>n.id===value):get(value))?.label||'主导航';if(typeof value==='boolean')return value?'开启':'关闭';if(key==='badgePlace')return value==='icon'?'图标右上角':'名称右侧';if(key==='badgeTone')return {gold:'品牌金',blue:'信息蓝',neutral:'中性灰'}[value]||'默认';return value||'无';}
function diffHtml(){return changes().map(c=>{const n=c.node,b=c.before;return `<div class="diff-item"><strong>${esc((n||b).label)} <span class="tag neutral">${!n?'删除分类':!b?'新增分类':'修改'}</span></strong>${n&&b?Object.keys(fieldNames).filter(k=>n[k]!==b[k]).map(k=>`<p>${fieldNames[k]}：<span class="before">${esc(displayValue(k,b[k],true))}</span> → ${esc(displayValue(k,n[k]))}</p>`).join(''):`<p>${n?'创建新分类，空分类暂不展示':'仅删除导航配置中的空分类'}</p>`}</div>`;}).join('');}
function openPublish(){const error=validate();if(error){selected=error.id;refresh();toast(error.message);return;}const count=changes().length,empty=draft.filter(n=>n.kind==='group'&&!descendants(n.id).some(x=>x.kind==='page')).length,hidden=draft.filter(n=>n.kind==='page'&&!effectiveVisible(n)).length;openModal('确认导航变更',`<p>演示版本 V${version} → V${version+1} · 共 ${count} 项变更</p><div class="diff-list">${diffHtml()}</div><div class="publish-info">${hidden?`${hidden} 个页面入口将保持隐藏。`:''}${empty?`${empty} 个空分类不会显示。`:''}本次仅更新浏览器内的演示版本，不影响真实系统。</div>`,cancelButton+'<button class="primary" type="submit">确认模拟发布</button>',()=>{const previous={version,published,history:clone(history)};version++;published=clone(draft);history.unshift({version,time:new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'2-digit',day:'2-digit',hour:'2-digit',minute:'2-digit'}).format(new Date())+' 北京时间',summary:`${count} 项导航变更`,nodes:clone(draft)});if(!persist()){({version,published,history}=previous);return;}closeModal();refresh();toast(`演示版本 V${version} 已更新`);});}
function openHistory(){openModal('版本记录',`<p>选择历史版本恢复为草稿，预览确认后再发布。</p>${history.map(h=>`<div class="history-row"><div><strong>V${h.version} ${h.version===version?'<span class="tag gold">当前版本</span>':''}</strong><p>${esc(h.time)} · ${esc(h.summary)}</p></div><button type="button" data-restore="${h.version}">恢复为草稿</button></div>`).join('')}`,cancelButton);$('modal-body').onclick=e=>{const b=e.target.closest('[data-restore]');if(!b)return;const target=history.find(h=>h.version===Number(b.dataset.restore));closeModal();openModal('恢复历史版本为草稿',`<p>使用 V${target.version} 覆盖当前演示草稿。当前尚未发布的编辑将被替换，已发布版本保持 V${version}。</p>`,cancelButton+'<button class="primary" type="submit">恢复为草稿</button>',()=>{draft=clone(target.nodes);if(!get(selected))selected='invoice';closeModal();refresh();toast('历史版本已载入草稿，请检查差异后发布');});};}
$('tree').onclick=e=>{const toggle=e.target.closest('[data-expand]'),select=e.target.closest('[data-select]');if(toggle){const id=toggle.dataset.expand;expanded.has(id)?expanded.delete(id):expanded.add(id);renderTree();}else if(select){selected=select.dataset.select;refresh();}else if(e.target.id==='clear-filter'){query='';filter='all';$('search').value='';document.querySelectorAll('[data-filter]').forEach(b=>b.classList.toggle('active',b.dataset.filter===filter));refresh();}};
$('tree').ondragstart=e=>{const grip=e.target.closest('[data-drag]');if(!grip||query||filter!=='all'||get(grip.dataset.drag).protected){e.preventDefault();return;}dragged=grip.dataset.drag;e.dataTransfer.setData('text/plain',dragged);e.dataTransfer.effectAllowed='move';};
$('tree').ondragover=e=>{const row=e.target.closest('[data-node]'),n=row&&get(row.dataset.node);if(!n||!dragged||n.parent!==get(dragged).parent||n.protected)return;e.preventDefault();document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));row.classList.add('drag-over');};
$('tree').ondrop=e=>{e.preventDefault();const row=e.target.closest('[data-node]'),target=row&&get(row.dataset.node),source=get(dragged);if(target&&source&&target.parent===source.parent&&!target.protected){const items=children(source.parent).filter(n=>n.id!==source.id);items.splice(items.findIndex(n=>n.id===target.id),0,source);items.forEach((n,i)=>n.order=i);selected=source.id;refresh();toast('同级顺序已更新');}dragged='';document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));};
$('tree').ondragend=()=>{dragged='';document.querySelectorAll('.drag-over').forEach(x=>x.classList.remove('drag-over'));};
$('search').oninput=e=>{query=e.target.value.trim();renderTree();renderEditor();status();};document.querySelectorAll('[data-filter]').forEach(b=>b.onclick=()=>{filter=b.dataset.filter;document.querySelectorAll('[data-filter]').forEach(x=>x.classList.toggle('active',x===b));refresh();});
$('fold-all').onclick=()=>{expanded.clear();renderTree();};$('new-btn').onclick=()=>openNew();$('compact-btn').onclick=()=>{compact=!compact;$('compact-btn').setAttribute('aria-pressed',String(compact));renderPreview();};$('save-btn').onclick=()=>{if(validate())return;if(persist()){status();toast('草稿已保存到此浏览器，尚未发布');}};$('publish-btn').onclick=openPublish;$('history-btn').onclick=openHistory;
window.addEventListener('beforeunload',e=>{if(JSON.stringify(draft)!==saved){e.preventDefault();e.returnValue='';}});
refresh();
if(storageError)toast(storageError);
